import json
import re
from datetime import datetime

# Function to add a todo item with tags
def add_todo(title, due=None, tags=None):
    if tags is None:
        tags = []
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9-]*$', title):
        print('Invalid title. Title must start with a letter or digit and may contain letters, digits, and hyphens only.')
        return
    for tag in tags:
        if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9-]*$', tag):
            print('Invalid tag. Tag must start with a letter or digit and may contain letters, digits, and hyphens only.')
            return
    with open('todo.json', 'r') as f:
        todos = json.load(f)
    todos.append({'title': title, 'due': due, 'tags': list(set(tags))})
    with open('todo.json', 'w') as f:
        json.dump(todos, f, indent=4)

# Function to list todo items with optional filtering and sorting
def list_todos(tags=None, sort_key=None):
    with open('todo.json', 'r') as f:
        todos = json.load(f)
    if tags:
        todos = [todo for todo in todos if all(tag.lower() in todo['tags'] for tag in tags)]
    if sort_key:
        if sort_key == 'title':
            todos.sort(key=lambda x: x['title'].lower())
        elif sort_key == 'due':
            todos.sort(key=lambda x: (x['due'] is None, x['due']), key=lambda x: x['due'] is None)
